let a=$json.alert;
if(typeof a==='string'){try{a=JSON.parse(a)}catch{a=null}}
if(!a || !a.alert_key || !a.destination_id || !['warning','critical'].includes(a.severity)){
  throw new Error('INCIDENT_ALERT_ENVELOPE_INVALID');
}
const clean=v=>String(v??'').replace(/[<>]/g,'').replace(/[\u0000-\u001f\u007f]/g,' ').slice(0,1000);
const prefix=a.severity==='critical'?'CRITICAL':'WARNING';
const lines=[
  '*Revenue Intelligence Agent — '+prefix+'*',
  '*Component:* '+clean(a.component_key),
  '*Alert:* '+clean(a.alert_type),
  '*Summary:* '+clean(a.summary),
  a.first_observed_at?'*First observed:* '+clean(a.first_observed_at):null
].filter(Boolean);
return {
  incident:a,
  slack_payload:{
    channel_id:a.destination_id,
    text:lines.join('\n')
  }
};

const original=$('REP | Build Incident Slack Payload').item.json;
const response=$json??{};
return {
  incident:original.incident,
  delivery_result:{
    status:'delivered',
    provider:'slack',
    message_ref:response.ts??response.message?.ts??null,
    delivered_at:new Date().toISOString()
  }
};
